namespace SirketMotoru.CanliPano;

internal static class YazilimBorsasiHtml
{
    public const string Icerik = """
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Yazılım Borsası V8.2</title>
<style>
:root{color-scheme:dark;--bg:#040812;--p:#0b1525;--p2:#111f34;--l:#29415f;--t:#eef7ff;--m:#91a8c5;--g:#43e1a0;--b:#61a8ff;--r:#ff6b7d;--y:#ffd166;--v:#bd8cff}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 7% 0,#14365f 0,transparent 34%),radial-gradient(circle at 93% 0,#321c59 0,transparent 30%),var(--bg);color:var(--t);font-family:Segoe UI,Arial,sans-serif}body{padding:9px}.shell{max-width:2400px;margin:auto}.top{position:sticky;top:4px;z-index:20;display:flex;justify-content:space-between;gap:12px;align-items:center;padding:12px 15px;border:1px solid var(--l);border-radius:15px;background:#071220f2}.brand{font-size:19px;font-weight:1000}.brand small{display:block;color:var(--m);font-size:9px;margin-top:3px}.status,.tabs,.row,.tags{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.pill,.tag{padding:5px 8px;border:1px solid var(--l);border-radius:999px;background:#0a1729;color:var(--m);font-size:9px}.tabs{margin:10px 0}.tab{cursor:pointer;border:1px solid var(--l);border-radius:999px;padding:8px 11px;background:#0a1628;color:var(--m);font-weight:900}.tab.active{background:linear-gradient(135deg,var(--g),var(--b));color:#03151c}.ticker{display:flex;align-items:center;overflow:hidden;border:1px solid #765d2a;background:#21180c;border-radius:10px;margin:9px 0;white-space:nowrap}.tickerTrack{display:inline-block;padding:9px 0;animation:ticker 280s linear infinite;color:var(--y);font-size:10px;font-weight:800}.ticker:hover .tickerTrack,.ticker.paused .tickerTrack{animation-play-state:paused}@keyframes ticker{from{transform:translateX(100vw)}to{transform:translateX(-100%)}}.ticker button{margin:4px;cursor:pointer;background:#2b2111;color:var(--y);border:1px solid #765d2a;border-radius:7px;padding:5px 8px}.metrics{display:grid;grid-template-columns:repeat(9,minmax(105px,1fr));gap:7px}.metric,.item,.card{border:1px solid var(--l);border-radius:12px;background:linear-gradient(180deg,var(--p2),#091423)}.metric{padding:9px}.metric span,.sub{display:block;color:var(--m);font-size:8px}.metric b{display:block;margin-top:5px;font-size:15px;white-space:nowrap}.card{padding:12px;margin-bottom:10px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.item{padding:10px}.item h3{margin:0 0 4px;font-size:13px}.item p{margin:4px 0;color:var(--m);font-size:9px}.title{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:8px}.title h2{margin:0;font-size:15px}.tablewrap{overflow:auto;max-height:760px;scrollbar-gutter:stable;overscroll-behavior:contain}table{width:100%;border-collapse:collapse;min-width:1050px;font-size:9px}th{position:sticky;top:0;background:#101c30;color:var(--m);padding:8px;text-align:left;z-index:2}td{padding:8px;border-bottom:1px solid #1b2a41;vertical-align:top}.good{color:var(--g)}.bad{color:var(--r)}.warn{color:var(--y)}.notice{padding:10px;border:1px solid var(--l);border-radius:10px;color:var(--m);margin:8px 0}.donuts{display:grid;grid-template-columns:repeat(4,minmax(210px,1fr));gap:9px}.donutBox{padding:10px;border:1px solid var(--l);border-radius:12px;background:var(--p)}.donut{width:150px;height:150px;border-radius:50%;margin:8px auto;position:relative}.donut:after{content:'';position:absolute;inset:27px;border-radius:50%;background:var(--p)}.legend{font-size:9px;color:var(--m)}.sw{display:inline-block;width:9px;height:9px;border-radius:3px;margin-right:4px}.news{padding:8px 0;border-bottom:1px solid var(--l);font-size:10px}.bar{height:7px;background:#14233a;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--b),var(--g))}@media(max-width:1600px){.metrics{grid-template-columns:repeat(5,1fr)}.grid4,.donuts{grid-template-columns:repeat(2,1fr)}}@media(max-width:900px){.top{position:static;flex-direction:column;align-items:flex-start}.metrics,.grid,.grid3,.grid4,.donuts{grid-template-columns:1fr}}
</style></head><body><div class="shell"><header class="top"><div class="brand">YAZILIM BORSASI V8.2<small>Tek render kökü · gerçek OS müşterisi · sabit hizmet fiyatları</small></div><div class="status"><span class="pill">Motor <b id="conn">Bağlanıyor</b></span><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Panel <b id="panelName">Ana Sayfa</b></span><span class="pill">Son veri <b id="updated">—</b></span></div></header><div id="tickerBox" class="ticker"><button id="pause">⏸</button><div style="overflow:hidden;flex:1"><div id="ticker" class="tickerTrack">Haberler hazırlanıyor…</div></div></div><section id="metrics" class="metrics"></section><nav id="tabs" class="tabs"></nav><main id="viewRoot"></main></div>
<script>
'use strict';const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(Number(v||0)),num=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(Number(v||0)),int=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(Number(v||0));
const TABS=[['home','Ana Sayfa'],['companies','Şirketler'],['apps','Uygulamalar'],['systems','İşletim Sistemleri'],['charts','Pazar Grafikleri'],['services','Hizmetler'],['customers','Müşteri CV'],['finance','Finans'],['penalties','Cezalar'],['news','Haberler'],['flow','Canlı Akış']];const S={d:null,active:TABS.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'home',lastTick:-1,loading:false,scrolling:false,scrollTimer:null,paused:false};
function tabs(){$('#tabs').innerHTML=TABS.map(x=>`<button class="tab ${S.active===x[0]?'active':''}" data-tab="${x[0]}">${x[1]}</button>`).join('');$('#panelName').textContent=TABS.find(x=>x[0]===S.active)?.[1]||S.active}function view(id){if(!TABS.some(x=>x[0]===id))id='home';S.active=id;history.replaceState(null,'',`#${id}`);tabs();render(true)}
async function refresh(force=false){if(S.loading||S.scrolling)return;S.loading=true;try{const r=await fetch('/api/durum',{cache:'no-store'});const d=await r.json();S.d=d;const tick=Number(d.motor?.tickNumarasi||0);$('#conn').textContent='Çalışıyor';$('#tick').textContent=tick;$('#updated').textContent=new Date().toLocaleTimeString('tr-TR');if(force||tick!==S.lastTick){S.lastTick=tick;render(false)}ticker()}catch{$('#conn').textContent='Bağlantı yok'}finally{S.loading=false}}
function metrics(d){const g=d.genel||{};return [['Bağlı şirket',`${int(g.bagliSirketSayisi)}/${int(g.toplamSirketSayisi)}`],['Şirket kasaları',money(g.toplamSirketKasasi)],['Tick gelir',money(g.toplamTickGeliri)],['Tick gider',money(g.toplamTickGideri)],['Tick net',money(g.toplamTickNeti)],['Piyasadaki uygulama',int(g.piyasadakiUygulamaSayisi)],['OS kullanan',int(g.isletimSistemiKullananMusteri)],['OS bekleyen',int(g.isletimSistemiBekleyenMusteri)],['Toplam müşteri',int(g.aktifMusteriSayisi)]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function render(force){if(!S.d)return;const y=window.scrollY;$('#metrics').innerHTML=metrics(S.d);$('#viewRoot').innerHTML=panel(S.active,S.d);requestAnimationFrame(()=>window.scrollTo(0,y))}
function panel(id,d){return ({home,companies,apps,systems,charts,services,customers,finance,penalties,news,flow}[id]||home)(d)}
function home(d){return `<div class="notice"><b>V8.2:</b> Hizmet ücretleri motorun sabit kataloğudur. Uygulama ve işletim sistemi fiyatları piyasada serbesttir. İşletim sistemi kullanıcıları gerçek müşteri CV seçimlerinden sayılır.</div>${companies(d)}${systems(d)}${apps(d)}${news(d)}`}
function companies(d){return `<div class="grid4">${(d.sirketler||[]).map(s=>`<div class="item"><div class="title"><h3>${esc(s.sirketAdi)}</h3><span class="tag ${s.bagli?'good':'bad'}">${s.bagli?'BAĞLI':'KAPALI'}</span></div><p>Kasa <b>${money(s.kasa)}</b></p><p>Tick gelir ${money(s.tickGelir)} · gider ${money(s.tickGider)}</p><p class="${Number(s.tickNetKazanc)>=0?'good':'bad'}">Net ${money(s.tickNetKazanc)}</p><p>Kalite ${num(s.kodKalitesiPuani)} · Perf ${num(s.performansPuani)} · Güv ${num(s.guvenlikPuani)}</p><p>Kredi ${int(s.krediNotu)} ${esc(s.krediSinifi)}</p></div>`).join('')}</div>`}
function apps(d){const xs=d.uygulamaPiyasasi||[];return `<div class="card"><div class="title"><h2>Uygulama ve ürün akışı</h2><span class="tag">Yayınlanan ürün kullanıcı sayısı 0 olsa da görünür</span></div><div class="tablewrap"><table><tr><th>Ürün</th><th>Şirket</th><th>Tür / kategori</th><th>Yayın</th><th>Aktif kullanıcı</th><th>Kapasite</th><th>Fiyat</th><th>Teknik durum</th></tr>${xs.map(x=>{const a=x.uygulama||{},u=x.urun||{},published=!!x.piyasada;return `<tr><td><b>${esc(a.uygulamaAdi)}</b><br><span class="sub">${esc(a.uygulamaKimligi)} v${esc(a.surum)}</span></td><td>${esc(x.sirketAdi)}</td><td>${esc(a.urunTuru)} / ${esc(a.kategori)}</td><td class="${published?'good':'warn'}">${published?(u.aktif?'Aktif':'Piyasada, pasif'):'Yayınlanmadı'}</td><td>${a.urunTuru==='isletim-sistemi'?int(x.gercekIsletimSistemiMusterisi):int(u.aktifKullaniciSayisi)}</td><td>${int(u.kullaniciKapasitesi)}</td><td>${money(Number(u.abonelikUcreti||0)+Number(u.kullanimBasinaUcret||0))}</td><td class="${x.dogrulama?.gecerli?'good':'bad'}">${esc(x.dogrulama?.durum||'—')}</td></tr>`}).join('')}</table></div></div>`}
function systems(d){const xs=d.isletimSistemiPazari||[],total=xs.reduce((a,x)=>a+Number(x.aktifMusteriSayisi||0),0);return `<div class="card"><div class="title"><h2>İşletim sistemi pazarı</h2><span class="tag">Gerçek müşteri: ${int(total)}</span></div><div class="grid3">${xs.map(x=>{const p=total?Number(x.aktifMusteriSayisi||0)*100/total:0;return `<div class="item"><h3>${esc(x.uygulamaAdi)}</h3><p>${esc(x.sirketAdi)} · v${esc(x.surum)}</p><p><b>${int(x.aktifMusteriSayisi)}</b> kullanıcı / ${int(x.kullaniciKapasitesi)}</p><div class="bar"><i style="width:${Math.min(100,p)}%"></i></div><p>%${num(p)} pazar payı · ${money(x.fiyat)}</p><p>Protokoller: ${(x.protokoller||[]).map(esc).join(', ')||'—'}</p></div>`}).join('')||'<div class="notice">Aktif işletim sistemi yok.</div>'}</div></div>`}
const colors=['#43e1a0','#61a8ff','#ffd166','#ff6b7d','#bd8cff','#58d7df','#ff9f5a','#9be564'];function donut(title,items){const total=items.reduce((a,x)=>a+Number(x.value||0),0);let acc=0,parts=[];items.forEach((x,i)=>{const start=total?acc/total*360:0;acc+=Number(x.value||0);const end=total?acc/total*360:0;parts.push(`${colors[i%colors.length]} ${start}deg ${end}deg`)});return `<div class="donutBox"><b>${esc(title)}</b><div class="donut" style="background:${total?`conic-gradient(${parts.join(',')})`:'#17243a'}"></div><div class="legend">${items.map((x,i)=>`<div><i class="sw" style="background:${colors[i%colors.length]}"></i>${esc(x.name)} — ${int(x.value)} (${total?num(Number(x.value)*100/total):0}%)</div>`).join('')||'Veri yok'}</div></div>`}
function charts(d){const os=(d.isletimSistemiPazari||[]).map(x=>({name:x.uygulamaAdi,value:x.aktifMusteriSayisi}));const cats=(d.kategoriPazarPaylari||[]).filter(x=>String(x.kategori||'').toLowerCase()!=='isletim-sistemi');const ds=[donut('İşletim sistemleri — gerçek müşteri',os),...cats.map(c=>donut(c.kategori,(c.uygulamalar||c.urunler||[]).map(x=>({name:x.uygulamaAdi||x.urunAdi||x.sirketAdi,value:x.aktifKullaniciSayisi||x.kullaniciSayisi||0}))))];return `<div class="notice">İşletim sistemi grafiği V6 ürün sayacından değil doğrudan 20.000 müşterinin OS seçiminden hesaplanır.</div><div class="donuts">${ds.join('')}</div>`}
function services(d){const xs=d.hizmetPiyasasi||[];return `<div class="notice">Bütün sağlayıcılar aynı motor fiyatını kullanır; hizmette fiyat rekabeti yoktur. Rekabet kalite, performans, güvenlik ve gerçek kapasitededir.</div><div class="tablewrap card"><table><tr><th>Hizmet</th><th>Motor fiyatı</th><th>Talep</th><th>Sağlayıcı</th><th>Bağlı sağlayıcılar / kapasite</th></tr>${xs.map(x=>{const ss=x.saglayicilar||[],f=ss[0]?.birimFiyat||0;return `<tr><td><b>${esc(x.hizmetKimligi)}</b><br>${esc(x.aciklama)}</td><td>${money(f)}</td><td>${int(x.talepSayisi)}</td><td>${int(x.saglayiciSayisi)}</td><td>${ss.map(s=>`${esc(s.sirketAdi)}: ${int(s.azamiEszamanliIs)} ${s.bagli?'✓':'✕'}`).join('<br>')||'—'}</td></tr>`}).join('')}</table></div>`}
function customers(d){const xs=d.musteriCvOrnekleri||[];return `<div class="card"><div class="title"><h2>Müşteri CV ekranı</h2><span class="tag">Tek DOM kökü — panel artık gelip gitmez</span></div><div class="tablewrap"><table><tr><th>Müşteri</th><th>Profil</th><th>Gelir</th><th>İşletim sistemi</th><th>Uygulamalar</th><th>Harcama</th><th>Başarı</th><th>Sadakat</th></tr>${xs.map(x=>`<tr><td><b>${esc(x.musteriAdi||x.musteriKimligi)}</b><br>${esc(x.musteriKimligi)}</td><td>${esc(x.meslekProfili)}<br>${esc(x.musteriTuru)}</td><td>${esc(x.gelirSegmenti)}<br>${money(x.bakiye)}</td><td>${esc(x.isletimSistemiKimligi||'OS bekliyor')}<br><span class="sub">Memnuniyet ${num(x.isletimSistemiMemnuniyeti)}</span></td><td>${(x.kullandigiUygulamalar||[]).map(esc).join(', ')||'—'}</td><td>${money(x.toplamHarcama)}</td><td>${int(x.basariliIsSayisi)} / ${int(x.basarisizIsSayisi)}</td><td>${esc(x.tercihEdilenSirketKimligi||'—')}</td></tr>`).join('')||'<tr><td colspan="8">CV örneği henüz üretilmedi.</td></tr>'}</table></div></div>`}
function finance(d){return `<div class="grid4">${(d.sirketler||[]).map(s=>`<div class="item"><h3>${esc(s.sirketAdi)}</h3><p>Gelir <b class="good">${money(s.tickGelir)}</b></p><p>Gider <b class="bad">${money(s.tickGider)}</b></p><p>Net <b class="${Number(s.tickNetKazanc)>=0?'good':'bad'}">${money(s.tickNetKazanc)}</b></p><p>Kasa ${money(s.kasa)} · Borç ${money(s.toplamBorc)}</p></div>`).join('')}</div>`}
function penalties(d){const x=d.cezaPiyasasi||{};return `<div class="grid3">${(x.sirketler||x.sirketOzetleri||[]).map(c=>`<div class="item"><h3>${esc(c.sirketAdi)}</h3><p>Bu tick ${money(c.buTickUygulananCeza)}</p><p>Affedilen ${money(c.buTickAffedilenCeza)}</p><p>Şirket kusuru ${int(c.sirketKusuruSayisi)} · Motor/sözleşme ${int(c.motorVeyaSozlesmeKusuruSayisi)}</p></div>`).join('')||'<div class="notice">Ceza özeti yok.</div>'}</div>`}
function news(d){return `<div class="card"><h2>Haber bülteni</h2>${(d.haberBulteni||[]).slice(0,120).map(x=>`<div class="news"><b>${esc(x.baslik||x.tur||'Haber')}</b> <span class="tag">Tick ${int(x.tickNumarasi)}</span><br>${esc(x.aciklama||x.mesaj||'')}</div>`).join('')||'<p class="sub">Henüz haber yok.</p>'}</div>`}
function flow(d){return `<div class="tablewrap card"><table><tr><th>Zaman</th><th>Seviye</th><th>Mesaj</th></tr>${(d.olaylar||[]).slice().reverse().map(x=>`<tr><td>${esc(x.zaman||x.olusturulmaZamani||'')}</td><td>${esc(x.seviye||x.tur||'')}</td><td>${esc(x.mesaj||x.aciklama||'')}</td></tr>`).join('')}</table></div>`}
function ticker(){const hs=S.d?.haberBulteni||[];$('#ticker').textContent=hs.slice(0,25).map(x=>`✦ ${x.baslik||x.tur||'Haber'} — ${x.aciklama||x.mesaj||''}`).join('       ')||'Piyasa sakin.'}
$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)view(b.dataset.tab)});$('#pause').onclick=()=>{S.paused=!S.paused;$('#tickerBox').classList.toggle('paused',S.paused);$('#pause').textContent=S.paused?'▶':'⏸'};window.addEventListener('hashchange',()=>view(location.hash.slice(1)));window.addEventListener('scroll',()=>{S.scrolling=true;clearTimeout(S.scrollTimer);S.scrollTimer=setTimeout(()=>{S.scrolling=false;refresh(false)},350)},{passive:true});tabs();refresh(true);setInterval(()=>refresh(false),900);
</script></body></html>
""";
}
